// Medical Research Council (MRC) Sum Score — seventh Clinical Tools
// calculator, first in a new "Strength" category (doesn't fit
// Independence or Balance & Falls Risk — it's a global strength/
// neuromuscular measure, most used to diagnose ICU-acquired weakness).
//
// Structurally similar to FIM: all 12 items share one 6-level rubric
// (MRC grade 0-5), so the rubric is defined once and every item is
// generated by combining it with a muscle (6) x side (2) grid, rather
// than authored per item. item.section groups by side (Right/Left) —
// the two are each 6 consecutive items, so CalculatorRunner's existing
// consecutive-section-collapsing renders exactly two subsections.
//
// No proprietary flag (not a licensed instrument), no descendingGood
// (higher = stronger = better, same orientation as every scale except
// mRS). interpretation bands operationalize the published diagnostic
// cutoffs (<48 = ICU-acquired weakness, <36 = severe) rather than an
// invented severity scheme.
//
// Usage: node db/seed/clinical-tools/mrc-sum-score.mjs
import { Pool } from "pg";
import { config } from "dotenv";
import { findOrCreate, upsertRelationship } from "../lib/toolkit.mjs";

config({ path: ".env.local" });

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const categoryId = await findOrCreate(pool, "clinical_calculator_category", "slug", "strength", {
  slug: "strength",
  name: "Strength",
  color: "orange",
  position: 2,
});

// ---------- Shared 6-level MRC grade rubric + muscle/side grid (English source) ----------

const GRADES_EN = [
  { value: 0, label: "No contraction", description: "No visible or palpable muscle contraction." },
  { value: 1, label: "Trace", description: "A flicker or trace of contraction is felt or seen, with no movement of the joint." },
  { value: 2, label: "Poor", description: "Active movement of the joint through full range with gravity eliminated." },
  { value: 3, label: "Fair", description: "Active movement of the joint through full range against gravity." },
  { value: 4, label: "Good", description: "Active movement of the joint through full range against gravity and some resistance." },
  { value: 5, label: "Normal", description: "Active movement of the joint through full range against gravity and full resistance." },
];

const MUSCLES_EN = [
  { id: "shoulder_abduction", label: "Shoulder abduction", instructions: "Deltoid — test with the arm abducted to 90°, resisting downward pressure." },
  { id: "elbow_flexion", label: "Elbow flexion", instructions: "Biceps brachii — test with the elbow flexed to 90°, resisting extension." },
  { id: "wrist_extension", label: "Wrist extension", instructions: "Extensor carpi radialis — test with the wrist extended, resisting flexion." },
  { id: "hip_flexion", label: "Hip flexion", instructions: "Iliopsoas — test with the hip flexed to 90°, resisting extension." },
  { id: "knee_extension", label: "Knee extension", instructions: "Quadriceps — test with the knee flexed to 90°, resisting flexion." },
  { id: "ankle_dorsiflexion", label: "Ankle dorsiflexion", instructions: "Tibialis anterior — test with the ankle dorsiflexed, resisting plantarflexion." },
];

const SIDES_EN = [
  { id: "right", label: "right", section: "Right side" },
  { id: "left", label: "left", section: "Left side" },
];

function buildItems(muscles, sides) {
  const items = [];
  for (const side of sides) {
    for (const muscle of muscles) {
      items.push({
        id: `${side.id}_${muscle.id}`,
        section: side.section,
        label: `${muscle.label} (${side.label})`,
        instructions: muscle.instructions,
      });
    }
  }
  return items;
}

function buildDefinition(muscles, sides, grades, calculationExplanation, interpretationBands) {
  return {
    items: buildItems(muscles, sides).map((item) => ({
      ...item,
      options: grades.map((g) => ({ value: g.value, label: g.label, description: g.description })),
    })),
    scoring: { method: "sum" },
    maxScore: 60,
    interpretation: interpretationBands,
    calculationExplanation,
    source: {
      citation: "Kleyweg RP, van der Meché FG, Schmitz PI. Interobserver agreement in the assessment of muscle strength and functional abilities in Guillain-Barré syndrome. Muscle Nerve. 1991;14(11):1103-1109.",
    },
  };
}

const calculationExplanationEn =
  "The MRC Sum Score is the sum of the Medical Research Council grade (0 to 5) for six muscle groups tested bilaterally — shoulder abduction, elbow flexion, wrist extension, hip flexion, knee extension, and ankle dorsiflexion — for a total of 12 muscle groups. The score ranges from 0 (complete paralysis in all groups) to 60 (normal strength throughout). A total score below 48 is the standard threshold used to diagnose ICU-acquired weakness.";

const interpretationEn = [
  { min: 0, max: 35, label: "Severe weakness", description: "Severe global weakness; strongly indicative of severe ICU-acquired weakness or a neuromuscular disorder.", severity: "critical" },
  { min: 36, max: 47, label: "Weakness present", description: "Score below the diagnostic threshold of 48, consistent with clinically significant generalized weakness (e.g. ICU-acquired weakness).", severity: "serious" },
  { min: 48, max: 60, label: "No significant weakness", description: "Score at or above the diagnostic threshold of 48; no clinically significant generalized weakness by this measure.", severity: "good" },
];

const definitionEn = buildDefinition(MUSCLES_EN, SIDES_EN, GRADES_EN, calculationExplanationEn, interpretationEn);

const calculatorFields = (definition) => ({
  category_id: categoryId,
  name: "Medical Research Council Sum Score",
  abbreviation: "MRC-SS",
  description: "Grades strength in six muscle groups on each side of the body, producing a global score out of 60 used to identify and track ICU-acquired weakness.",
  population: "Critically ill or neuromuscularly weak adults (e.g. ICU-acquired weakness, Guillain-Barré syndrome)",
  estimated_minutes_min: 5,
  estimated_minutes_max: 10,
  definition: JSON.stringify(definition),
  status: "published",
  position: 0,
});

const calculatorId = await findOrCreate(pool, "clinical_calculator", "slug", "mrc-sum-score", {
  slug: "mrc-sum-score",
  ...calculatorFields(definitionEn),
});
await pool.query(
  `UPDATE clinical_calculator
   SET category_id = $2, name = $3, abbreviation = $4, description = $5,
       population = $6, estimated_minutes_min = $7, estimated_minutes_max = $8,
       definition = $9, status = $10, position = $11
   WHERE id = $1`,
  [
    calculatorId,
    categoryId,
    "Medical Research Council Sum Score",
    "MRC-SS",
    "Grades strength in six muscle groups on each side of the body, producing a global score out of 60 used to identify and track ICU-acquired weakness.",
    "Critically ill or neuromuscularly weak adults (e.g. ICU-acquired weakness, Guillain-Barré syndrome)",
    5,
    10,
    JSON.stringify(definitionEn),
    "published",
    0,
  ]
);

// ---------- Translations ----------

// Translated muscle/side arrays carry only label/instructions (and
// section, for sides) — ids aren't translated, so they're merged back
// in from the English source here, the same way fim.mjs's
// translateDefinition preserves item.id from ITEMS_EN.
function translateDefinition(muscles, sides, grades, calculationExplanation, interpretationBands) {
  const mergedMuscles = MUSCLES_EN.map((m, i) => ({ ...muscles[i], id: m.id }));
  const mergedSides = SIDES_EN.map((s, i) => ({ ...sides[i], id: s.id }));
  return buildDefinition(mergedMuscles, mergedSides, grades, calculationExplanation, interpretationBands);
}

